using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using AICad.Contracts;
using AICad.Geometry;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Runtime;
using JsonUtil=AICad.Contracts.Json;
[assembly:CommandClass(typeof(AICad.Bridge.NativeTests))]
namespace AICad.Bridge;
// Tests only fresh in-memory databases, never the user's current DWG.
public sealed class NativeTests {
 [CommandMethod("AICADNATIVETEST",CommandFlags.Modal|CommandFlags.NoUndoMarker)]public void Run(){string root=Environment.GetEnvironmentVariable("AICAD_TEST_ROOT")??"";if(!Path.IsPathRooted(root)||!File.Exists(Path.Combine(root,".aicad-test-root")))throw new InvalidOperationException("Explicit isolated test root required.");var results=new List<object>();int passed=0;try{var install=JsonUtil.Read<InstallConfig>(File.ReadAllText(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(typeof(Plugin).Assembly.Location)!,"..","install.json"))));var template=JsonUtil.Read<TemplateProfile>(File.ReadAllText(Path.Combine(WarehousePaths.Folder(install.ContentRoot,"template-library"),"STARTER.json")));using var db=new Database(true,true);db.DisableUndoRecording(false);db.Insunits=UnitsValue.Millimeters;var plan=new DrawingPlan{SessionId=Guid.NewGuid().ToString("N"),DocumentId=Guid.NewGuid().ToString("N"),DocumentRevision="native:1",TaskId="NATIVE_TEST",Template=template,TemplateHash=JsonUtil.Hash(template),Scope=new(){new(-100,-100),new(6000,-100),new(6000,6000),new(-100,6000)}};plan.Operations=new(){new(){Kind="draw_line",Points=new(){new(100,100),new(900,100)}},new(){Kind="draw_polyline",Points=new(){new(100,200),new(900,200),new(900,700)},Closed=true},new(){Kind="draw_circle",Points=new(){new(1500,1500)},Radius=200},new(){Kind="draw_arc",Points=new(){new(2000,2000)},Radius=300},new(){Kind="add_text",Points=new(){new(100,1000)},Height=100,Text="Native CAD"},new(){Kind="insert_block",AssetId="DOOR_900",Points=new(){new(3000,3000)}}};Validation.Plan(plan);using(var tx=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);var model=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);foreach(var op in plan.Operations){var e=EntityFactory.Append(op,plan,db,tx);model.AppendEntity(e);tx.AddNewlyCreatedDBObject(e,true);EntityFactory.DemandBounds(e,plan);}tx.Commit();}results.Add(new{name="Six typed operations append with native bounds",passed=true});passed++;
 using(var tx=db.TransactionManager.StartOpenCloseTransaction()){var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);if(ms.Cast<ObjectId>().Count(id=>!id.IsErased)!=6)throw new System.Exception("Expected six native entities.");var types=ms.Cast<ObjectId>().Where(id=>!id.IsErased).Select(id=>tx.GetObject(id,OpenMode.ForRead).GetType().Name).ToArray();results.Add(new{name="Editable native entity types",passed=true,types});passed++;}
 try{using var tx=db.TransactionManager.StartTransaction();var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);var invalid=new Line(new Autodesk.AutoCAD.Geometry.Point3d(100000,0,0),new Autodesk.AutoCAD.Geometry.Point3d(200000,0,0));ms.AppendEntity(invalid);tx.AddNewlyCreatedDBObject(invalid,true);EntityFactory.DemandBounds(invalid,plan);throw new System.Exception("Outside scope was not rejected.");}catch(CadException e)when(e.Code=="OUTSIDE_SCOPE"){}using(var tx=db.TransactionManager.StartOpenCloseTransaction()){var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);if(ms.Cast<ObjectId>().Count(id=>!id.IsErased)!=6)throw new System.Exception("Rollback active entity count="+ms.Cast<ObjectId>().Count(id=>!id.IsErased)+" IDs="+string.Join(";",ms.Cast<ObjectId>().Select(id=>id.Handle+" erased="+id.IsErased)));}results.Add(new{name="Outside-scope native mutation rolls back",passed=true});passed++;
 db.DisableUndoRecording(true);try{NativeWriteGuard.CheckDatabase(db);throw new System.Exception("Disabled Undo was accepted.");}catch(CadException e)when(e.Code=="UNDO_DISABLED"){}finally{db.DisableUndoRecording(false);}results.Add(new{name="Disabled Undo blocks mutation before transaction",passed=true});passed++;string output=Path.Combine(root,"native-"+Guid.NewGuid().ToString("N")+".dwg");db.SaveAs(output,DwgVersion.AC1032);using(var reopened=new Database(false,true)){reopened.ReadDwgFile(output,FileOpenMode.OpenForReadAndAllShare,true,"");using var tx=reopened.TransactionManager.StartOpenCloseTransaction();var bt=(BlockTable)tx.GetObject(reopened.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);if(ms.Cast<ObjectId>().Count(id=>!id.IsErased)!=6)throw new System.Exception("DWG reopen mismatch.");}results.Add(new{name="Saved fixture DWG reopens with editable entities",passed=true});passed++;JsonUtil.Atomic(Path.Combine(root,"native-results.json"),new{passed,total=5,failed=0,output,cases=results});}catch(System.Exception e){JsonUtil.Atomic(Path.Combine(root,"native-results.json"),new{passed,total=5,failed=1,error=e.ToString(),cases=results});}}
}

